code.correct:
def flood_area(g, r, c):
    if r < 0 or r >= len(g) or c < 0 or c >= len(g[0]):
        return 0
    if g[r][c] != 1:
        return 0
    g[r][c] = 0
    return 1 + flood_area(g, r + 1, c) + flood_area(g, r - 1, c) + flood_area(g, r, c + 1) + flood_area(g, r, c - 1)

